permission_denials.command:
python3 -c "
import json, sys
try:
    import yaml, jsonschema
except ImportError as e:
    print('SKIP:', e); sys.exit(0)
text = open('journals/2026-08-19-products-3-500s.md').read()
fm = text.split('---\n')[1]
doc = yaml.safe_load(fm)
schema = json.load(open('.claude/skills/investigate/journal.schema.json'))
jsonschema.validate(doc, schema)
ids = {e['id'] for e in doc['evidence']}
for h in doc['hypotheses']:
    for r in h['evidence_for'] + h['evidence_against']:
        assert r in ids, r
assert doc['root_cause']['hypothesis'] in {h['id'] for h in doc['hypotheses'] if h['state']=='validated'}
print('schema OK, refs OK')
print('started', doc['investigation']['started'], 'concluded', doc['investigation']['concluded'], 'wall', doc['usage']['wall_clock_seconds'])
"
